"""Custom steps of destination `sas_study_bucket` — generated by package-factory 0.9.0. Do not edit: change the requirement and run `pkf create`."""
from __future__ import annotations

import logging
from botocore.exceptions import BotoCoreError, ClientError


MAX_KEY_BYTES = 1024


ERROR_PREFIX = "error/"


TAG_KEY = "ADDITIONAL_TAG"


TAG_EXTRA_CHARACTERS = "+-=._:/@"


MAX_TAG_VALUE_LENGTH = 256


PHASE_MESSAGES = {
    "copy": "copy failed: {}",
    "check": "check failed: {}",
    "delete": "delete failed: {} (target copied)",
}


def split_path(path: str) -> tuple[list[str], str, str]:
    """Split a package path into folders, file name and wrapped folder path.

    Args:
        path: Package path relative to incoming/.

    Returns:
        (folders, file name, wrapped folder path with leading and trailing '/').
    """
    parts = path.split("/")
    file_name = parts[-1]
    folders = [part for part in parts[:-1] if part != ""]
    wrapped = "/" + "/".join(folders) + "/" if folders else "/"
    return folders, file_name, wrapped


def data_format(wrapped: str) -> str | None:
    """Return the data format from the folder path (adam, sdtm, raw) or None.

    Args:
        wrapped: Wrapped folder path.

    Returns:
        The data format or None.
    """
    if "/adam/" in wrapped:
        return "adam"
    if "/sdtm/" in wrapped:
        return "sdtm"
    if "raw/" in wrapped:
        return "raw"
    return None


def underscore_format(wrapped: str) -> str | None:
    """Return the data format from the underscore markers of anonymised folders.

    Args:
        wrapped: Wrapped folder path.

    Returns:
        The data format or None.
    """
    if "_adam_" in wrapped:
        return "adam"
    if "_sdtm_" in wrapped:
        return "sdtm"
    if "_raw_" in wrapped or "_restricted_raw_" in wrapped:
        return "raw"
    return None


def matching_rules(wrapped: str) -> list[str]:
    """Check every rule and return the names of all matching rules, in rule order.

    Args:
        wrapped: Wrapped folder path.

    Returns:
        The names of the matching rules.
    """
    has_format = data_format(wrapped) is not None
    has_underscore_format = underscore_format(wrapped) is not None
    data_reuse = "/data_reuse/" in wrapped
    excluded = ("/med", "/cdap", "/idap", "/anon", "_anon_")
    checks = [
        ("CDAP", data_reuse and "/cdap_" in wrapped and has_format),
        ("IDAP", data_reuse and "/idap" in wrapped and has_format),
        ("MED", data_reuse and "/med" in wrapped and has_format),
        ("ANON", "_anon_" in wrapped and has_underscore_format),
        ("CDAR", "/cdar/" in wrapped and has_format),
        ("OTHERS", data_reuse and has_format and not any(marker in wrapped for marker in excluded)),
        ("DEFAULT", not any(marker in wrapped for marker in ("/data_reuse/", "_anon_", "/cdar/"))),
    ]
    return [name for name, matched in checks if matched]


def ia_label(part: str) -> str:
    """Write an interim part as ia_ + the rest.

    Args:
        part: The interim folder part (e.g. ia300, ia_psc, IA5).

    Returns:
        The label, e.g. ia_300.

    Raises:
        ValueError: When nothing is left after removing 'ia' and leading '_'.
    """
    rest = part[2:] if part.lower().startswith("ia") else part
    rest = rest.lstrip("_")
    if rest == "":
        raise ValueError("empty interim label")
    return "ia_" + rest


def target_cdap(folders: list[str], file: str, wrapped: str, fmt: str) -> str:
    """Build the CDAP key: primary, interim or other.

    Args:
        folders: Folders of the path.
        file: File name.
        wrapped: Wrapped folder path.
        fmt: Data format.

    Returns:
        The target key.

    Raises:
        ValueError: When the last folder has too few '_' parts.
    """
    study = folders[0]
    last = folders[-1]
    if "/cdap_csr" in wrapped:
        return f"{study}/extended_primary_use/primary/{fmt}/{file}"
    parts = last.split("_")
    if "_ia" in last:
        if len(parts) < 3:
            raise ValueError("CDAP interim: fewer than 3 parts in last folder")
        return f"{study}/extended_primary_use/interim/{fmt}/{ia_label(parts[2])}/{file}"
    if len(parts) < 2:
        raise ValueError("CDAP other: fewer than 2 parts in last folder")
    return f"{study}/extended_primary_use/other/{fmt}/{parts[1]}/{file}"


def target_anon(folders: list[str], file: str, wrapped: str, ufmt: str) -> str:
    """Build the ANON key: primary, interim or other.

    Args:
        folders: Folders of the path.
        file: File name.
        wrapped: Wrapped folder path.
        ufmt: Underscore data format.

    Returns:
        The target key.

    Raises:
        ValueError: When the last '_' part is empty.
    """
    study = folders[0]
    last = folders[-1]
    if "_anon_csr" in wrapped:
        return f"{study}/anonymised/primary/{ufmt}/{file}"
    part = last.split("_")[-1]
    if part.startswith("ia"):
        return f"{study}/anonymised/interim/{ufmt}/{ia_label(part)}/{file}"
    if part == "":
        raise ValueError("ANON: empty last part")
    return f"{study}/anonymised/other/{ufmt}/{part}/{file}"


def target_cdar(folders: list[str], file: str, fmt: str) -> str:
    """Build the CDAR key from the reporting level after the 'ar' folder.

    Args:
        folders: Folders of the path.
        file: File name.
        fmt: Data format.

    Returns:
        The target key.

    Raises:
        ValueError: When there is no reporting level or it is a data format.
    """
    ar_indexes = [index for index, folder in enumerate(folders) if folder.lower() == "ar"]
    if not ar_indexes or ar_indexes[0] == len(folders) - 1:
        raise ValueError("CDAR: no reporting level after ar")
    level = folders[ar_indexes[0] + 1]
    low = level.lower()
    if low in ("adam", "sdtm", "raw"):
        raise ValueError(f"CDAR: reporting level is {low}")
    study = folders[0]
    if low == "csr":
        return f"{study}/primary/complete/{fmt}/{file}"
    if low.startswith("ia"):
        return f"{study}/primary/interim/{fmt}/{ia_label(level)}/{file}"
    return f"{study}/primary/other/{fmt}/{level}/{file}"


def decide_route(path: str) -> tuple[str, str]:
    """Return the final key and the rule name or error reason for one file.

    Args:
        path: Package path relative to incoming/.

    Returns:
        (target key, rule name or error reason).
    """
    folders, file_name, wrapped = split_path(path)
    error_key = ERROR_PREFIX + path
    rules = matching_rules(wrapped)
    if len(rules) == 0:
        return error_key, "error: no rule matches"
    if len(rules) > 1:
        return error_key, "error: several rules match: " + ",".join(rules)
    rule = rules[0]
    fmt = data_format(wrapped)
    ufmt = underscore_format(wrapped)
    builders = {
        "CDAP": lambda: target_cdap(folders, file_name, wrapped, fmt),
        "IDAP": lambda: f"{folders[0]}/internal_reuse/{fmt}/{folders[-1]}/{file_name}",
        "MED": lambda: f"{folders[0]}/external_reuse/{fmt}/{folders[-1]}/{file_name}",
        "ANON": lambda: target_anon(folders, file_name, wrapped, ufmt),
        "CDAR": lambda: target_cdar(folders, file_name, fmt),
        "OTHERS": lambda: f"{folders[0]}/other/{fmt}/{folders[-1]}/{file_name}",
        "DEFAULT": lambda: path,
    }
    try:
        key = builders[rule]()
    except ValueError as exc:
        return error_key, f"error: {rule}: {exc}"
    if len(key.encode("utf-8")) > MAX_KEY_BYTES:
        return error_key, "error: key longer than 1024 bytes"
    return key, rule


def route_by_folder_rules(layout, params, ctx):
    """Set each unplaced file's target key from its folder path with the seven study rules.

    Implements R-DST-1 to R-DST-29: every rule is checked, exactly one must match, and anything
    unclear goes to error/{path}, so no key is None and no file is dropped.

    Args:
        layout: The layout (files, keys, vars).
        params: Run variables.
        ctx: Run context.

    Returns:
        The layout with every file's key set.
    """
    logger = logging.getLogger(__name__)
    keys = layout.setdefault("keys", {})
    for path in layout["files"]:
        if keys.get(path) is not None:
            continue
        key, label = decide_route(path)
        keys[path] = key
        logger.info("route %s -> %s (%s)", path, key, label)
    return layout


def is_error_target(key: str) -> bool:
    """Return whether a target key is under the error/ prefix.

    Args:
        key: Target object key.

    Returns:
        True when the key starts with error/.
    """
    return key.startswith(ERROR_PREFIX)


def tag_value_ok(value: str) -> bool:
    """Return whether a string is a valid S3 tag value.

    Args:
        value: Candidate tag value.

    Returns:
        True when the value is at most 256 characters of letters, digits, whitespace or '+-=._:/@'.
    """
    if len(value) > MAX_TAG_VALUE_LENGTH:
        return False
    return all(char.isalnum() or char.isspace() or char in TAG_EXTRA_CHARACTERS for char in value)


def report_line(source_key: str, target_key: str, detail: str) -> str:
    """Build the one-line report for a file.

    Args:
        source_key: Source object key.
        target_key: Target object key.
        detail: Rule name or error reason.

    Returns:
        The report line.
    """
    return f"source={source_key} target={target_key} reason={detail}"


def move_and_tag(transfers, params, ctx, aws):
    """Move each file (copy, check, delete source), tag study targets and report one line per file.

    Implements R-RUN-1 to R-RUN-12 and R-DST-28: managed server-side copy, size check, source delete
    only after a confirmed copy, ADDITIONAL_TAG replacing all tags on study targets (failure = warning),
    no tag change on error/ targets, one result and one report line per transfer.

    Args:
        transfers: One dict per file to deliver.
        params: Run variables.
        ctx: Run context with the delivery settings.
        aws: S3 clients and logger.

    Returns:
        One result dict per transfer.
    """
    delivery = ctx.get("delivery") or {}
    results = []
    for transfer in transfers:
        path, source_key, target_key = transfer["path"], transfer["source_key"], transfer["target_key"]
        source = {"Bucket": transfer["source_bucket"], "Key": source_key}
        target = {"Bucket": transfer["target_bucket"], "Key": target_key}
        label = decide_route(path)[1]  # noqa: F821  (route_by_folder_rules' helper, same module)
        to_error = is_error_target(target_key)
        optional = (
            ("CopySourceIfMatch", transfer.get("etag")),
            ("ServerSideEncryption", delivery.get("server_side_encryption")),
            ("SSEKMSKeyId", delivery.get("kms_key_id")),
        )
        extra = {name: value for name, value in optional if value}
        phase, failure, note = "copy", None, ""
        try:
            aws.s3_destination.copy(source, target["Bucket"], target_key, ExtraArgs=extra, SourceClient=aws.s3_source)
            phase = "check"
            head = aws.s3_destination.head_object(**target)
            failure = "check failed: size mismatch" if head["ContentLength"] != transfer["size"] else None
            if failure is None:
                phase = "delete"
                deleted = aws.s3_source.delete_object(**source)
                note = " (delete marker)" if deleted.get("DeleteMarker") else ""
        except (ClientError, BotoCoreError) as exc:
            failure = PHASE_MESSAGES[phase].format(exc)
        if failure is not None:
            aws.log.error(report_line(source_key, target_key, failure))
            results.append({"path": path, "key": target_key, "status": "failed", "detail": failure})
            continue
        tag_warning = ""
        if not to_error and not tag_value_ok(path):
            aws.log.warning("tag value not allowed for %s", target_key)
            tag_warning = " (tag warning: tag value not allowed)"
        elif not to_error:
            try:
                tag_set = {"TagSet": [{"Key": TAG_KEY, "Value": path}]}
                aws.s3_destination.put_object_tagging(**target, Tagging=tag_set)
            except (ClientError, BotoCoreError) as exc:
                aws.log.warning("tag warning for %s: %s", target_key, exc)
                tag_warning = f" (tag warning: {exc})"
        detail = label + note + tag_warning
        aws.log.info(report_line(source_key, target_key, detail))
        status = "moved_to_error" if to_error else "moved"
        results.append({"path": path, "key": target_key, "status": status, "detail": detail})
    return results
